mapper.select:
SELECT t.id, t.version, t.type_code, t.name, t.status, t.created_at, t.updated_at, t.created_by, t.updated_by FROM customer_type t WHERE t.deleted = FALSE
AND (t.type_code ILIKE CONCAT('%', #{query.keyword}, '%') OR t.name ILIKE CONCAT('%', #{query.keyword}, '%'))
AND t.status = #{query.status}

mapper.update:
UPDATE customer_type
SET deleted    = TRUE,
    version    = version + 1,
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{operator}
WHERE id = #{typeId}
  AND version = #{version}
  AND deleted = FALSE
